struct input_iterator_tag {};
struct forward_iterator_tag : input_iterator_tag {};
struct random_access_iterator_tag : forward_iterator_tag {};

// Template with Default Parameter (RA access is typical default)
template <typename T,
          typename Category = random_access_iterator_tag>
struct GenericContainer {
    using iterator_tag = Category;
    T value;
};

// Tag Dispatching Overloads (Implementation specialization)
void algorithm_impl(input_iterator_tag) { /* Generic, slow implementation */ }
void algorithm_impl(random_access_iterator_tag) { /* Specialized, fast */ }

template <typename C>
void specialized_algo(C container) {
    // Compile-time dispatch via tag type
    algorithm_impl(typename C::iterator_tag{});
}
